// Recipe data and the ranking behind the Recipes page.
//
// public/recipes.json is generated by datasets/scripts/build_recipes.py from
// the committed recipe CSV. Every ingredient line that names something the
// detector can see carries that class key, which is what links a pantry to a dish.

import { useEffect, useState } from 'react';
import { displayName } from './classNames';
import { Member } from './store';

export type RecipeStep = { title: string; detail: string; seconds: number };

export type Recipe = {
  id: string;
  name: string;
  minutes: number;
  servings: number;
  cuisine: string;
  course: string;
  diet: 'veg' | 'egg' | 'nonveg';
  core: string[]; // class keys the dish needs, minus assumed staples
  ingredients: { text: string; key?: string }[];
  steps: RecipeStep[];
  url: string;
};

export const FILTERS = ['Veg', 'Low GI', 'High protein', 'Quick'] as const;

const HIGH_GI = new Set([
  'sugar', 'jaggery', 'maida_flour', 'potato', 'sona_masoori_rice', 'basmati_rice',
  'idli_rice', 'sooji_rava', 'rice_flour', 'sweetcorn',
]);
const PROTEIN = new Set([
  'paneer', 'eggs', 'raw_chicken', 'raw_fish', 'raw_mutton', 'raw_prawn', 'toor_dal',
  'chana_dal', 'masoor_dal', 'urad_dal', 'moong_dal_split', 'moong_whole', 'chickpea',
  'kala_chana', 'black_eyed_peas',
]);
const SAT_FAT = new Set(['ghee', 'butter', 'cream', 'raw_mutton']);
const ACIDIC = new Set(['chilli pepper', 'dry red chilly', 'tamarind', 'tomato', 'lemon', 'kokum']);

// Ingredient -> nutrients it is a good source of, for the pantry graph.
export const NUTRIENTS: Record<string, string[]> = {
  Protein: [...PROTEIN, 'milk', 'curd_yogurt', 'besan_flour', 'almond', 'cashew', 'pistachio', 'walnut', 'peas'],
  Iron: ['spinach', 'methi_leaves', 'drumstick_leaves', 'beetroot', 'jaggery', 'kala_chana', 'masoor_dal', 'bajra_flour', 'raisin'],
  Calcium: ['milk', 'paneer', 'curd_yogurt', 'ragi_flour', 'drumstick_leaves', 'almond', 'poppy seeds'],
  'Vitamin C': ['tomato', 'lemon', 'orange', 'capsicum', 'chilli pepper', 'kiwi', 'pineapple', 'cabbage', 'cauliflower', 'coriander_leaves', 'mango', 'raddish'],
  'Vitamin A': ['carrot', 'spinach', 'sweetpotato', 'mango', 'methi_leaves', 'drumstick_leaves'],
  Fibre: ['atta_flour', 'jowar_flour', 'bajra_flour', 'ragi_flour', 'carrot', 'peas', 'apple', 'pear', 'chickpea', 'kala_chana', 'moong_whole', 'black_eyed_peas', 'sweetpotato', 'cabbage', 'beetroot'],
};

function keysOf(r: Recipe): Set<string> {
  const s = new Set<string>();
  for (const i of r.ingredients) if (i.key) s.add(i.key);
  return s;
}

export function tagsOf(r: Recipe): string[] {
  const keys = keysOf(r);
  const tags: string[] = [];
  if (r.diet === 'veg') tags.push('Veg');
  if (r.diet === 'egg') tags.push('Egg');
  if (r.diet === 'nonveg') tags.push('Non-veg');
  if (![...keys].some((k) => HIGH_GI.has(k))) tags.push('Low GI');
  if (r.core.some((k) => PROTEIN.has(k))) tags.push('High protein');
  if (r.minutes <= 30) tags.push('Quick');
  return tags;
}

export type Scored = {
  recipe: Recipe;
  match: number;
  have: string[];
  missing: string[];
  tags: string[];
  reasons: { label: string; value: number }[];
  notes: string[];
};

function list(keys: string[]): string {
  return keys.map((k) => displayName(k).toLowerCase()).join(', ');
}

/**
 * match = 60% pantry coverage + 25% family fit + 15% speed.
 * Family fit starts at 100 and loses points for ingredients that work against
 * a condition someone at the table has. Rule-based, and shown as such.
 */
export function scoreRecipe(r: Recipe, pantry: Set<string>, members: Member[]): Scored {
  const have = r.core.filter((k) => pantry.has(k));
  const missing = r.core.filter((k) => !pantry.has(k));
  const coverage = Math.round((have.length / r.core.length) * 100);

  const keys = [...keysOf(r)];
  const deepFried = r.steps.some((s) => /deep[- ]?fr/i.test(s.detail));
  let fit = 100;
  const notes: string[] = [];
  const who = (test: RegExp) => members.filter((m) => test.test(m.disease)).map((m) => m.name || 'someone');

  const diabetic = who(/diabet|sugar/i);
  const gi = keys.filter((k) => HIGH_GI.has(k));
  if (diabetic.length && gi.length) {
    fit -= Math.min(45, gi.length * 15);
    notes.push(`Contains ${list(gi)}: quick to raise blood sugar (${diabetic.join(', ')}).`);
  }
  const cardiac = who(/cholesterol|heart|cardio|hypertens|\bbp\b|pressure/i);
  const fat = keys.filter((k) => SAT_FAT.has(k));
  if (cardiac.length && (fat.length || deepFried)) {
    fit -= Math.min(40, fat.length * 12 + (deepFried ? 16 : 0));
    const what = [fat.length ? list(fat) : '', deepFried ? 'deep frying' : ''].filter(Boolean).join(' and ');
    notes.push(`Uses ${what}: heavy on saturated fat (${cardiac.join(', ')}).`);
  }
  const reflux = who(/reflux|acid|gerd|ulcer/i);
  const acid = keys.filter((k) => ACIDIC.has(k));
  if (reflux.length && acid.length) {
    fit -= Math.min(36, acid.length * 12);
    notes.push(`Contains ${list(acid)}: common acid-reflux triggers (${reflux.join(', ')}).`);
  }
  fit = Math.max(0, fit);
  if (notes.length === 0) notes.push('Nothing in it conflicts with the conditions on your Family page.');

  const speed = Math.round(Math.max(20, Math.min(100, 100 - (r.minutes - 15) * 1.4)));
  const match = Math.round(coverage * 0.6 + fit * 0.25 + speed * 0.15);

  return {
    recipe: r,
    match,
    have,
    missing,
    tags: tagsOf(r),
    reasons: [
      { label: 'Uses what you have', value: coverage },
      { label: 'Fits your family', value: fit },
      { label: 'Quick to cook', value: speed },
    ],
    notes,
  };
}

export function rankRecipes(recipes: Recipe[], pantry: Set<string>, members: Member[]): Scored[] {
  return recipes
    .map((r) => scoreRecipe(r, pantry, members))
    .sort((a, b) => b.match - a.match || a.recipe.minutes - b.recipe.minutes);
}

let cache: Promise<Recipe[]> | null = null;

function fetchRecipes(): Promise<Recipe[]> {
  if (!cache) {
    cache = fetch(`${import.meta.env.BASE_URL}recipes.json`)
      .then((res) => {
        if (!res.ok) throw new Error(`Could not load recipes (${res.status}).`);
        return res.json() as Promise<Recipe[]>;
      })
      .catch((e) => {
        cache = null; // let Retry fetch again
        throw e;
      });
  }
  return cache;
}

export type RecipesState =
  | { status: 'loading'; recipes: Recipe[] }
  | { status: 'ready'; recipes: Recipe[] }
  | { status: 'error'; recipes: Recipe[]; error: string };

export function useRecipes(): RecipesState & { retry: () => void } {
  const [state, setState] = useState<RecipesState>({ status: 'loading', recipes: [] });
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let live = true;
    setState({ status: 'loading', recipes: [] });
    fetchRecipes()
      .then((recipes) => live && setState({ status: 'ready', recipes }))
      .catch((e: unknown) =>
        live && setState({ status: 'error', recipes: [], error: e instanceof Error ? e.message : String(e) }),
      );
    return () => { live = false; };
  }, [attempt]);

  return { ...state, retry: () => setAttempt((n) => n + 1) };
}
